import { useRef, useState, useEffect } from 'react'
import { useNavigate } from 'react-router-dom'
import {
    getOrderList,
    OrderManagementTypes
} from '@/apis/admin/order-management'
import { getServiceTypeList } from '@/apis/admin/system-config'
import ExcelTable from '@/components/exportExcel'
import AlertBanner from './components/AlertBanner'
import {
    ActionType,
    ProFormInstance,
    ProColumns,
} from '@ant-design/pro-components'
import {
    Button,
    message,
    Tag,
    Badge,
    Tooltip,
    Modal,
    Card,
} from 'antd'
import {
    EyeOutlined,
    ClockCircleOutlined,
    ExclamationCircleOutlined,
    FileTextOutlined,
    CommentOutlined,
} from '@ant-design/icons'
import { ResultEnum } from '@/utils/enums/httpEnum'
import dayjs from 'dayjs'
import { ORDER_STATUS_MAP, ORDER_STATUS_VALUE_ENUM } from '@/constants'

// 格式化时间戳
const formatTime = (timestamp: number) => {
    if (!timestamp) {
return '-'
}
    return dayjs(timestamp * 1000).format('YYYY-MM-DD HH:mm:ss')
}

const OrderList: React.FC = () => {
    const actionRef = useRef<ActionType>()
    const formRef = useRef<ProFormInstance>()
    const navigate = useNavigate()
    const [serviceTypeOptions, setServiceTypeOptions] = useState<Record<string, { text: string }>>({})
    const [remarkModalVisible, setRemarkModalVisible] = useState(false)
    const [selectedRemark, setSelectedRemark] = useState<{ orderSn: string; remark: string } | null>(null)
    const [overdueCount, setOverdueCount] = useState(5)

    // 加载服务类型列表
    const loadServiceTypeList = async () => {
        try {
            const res = await getServiceTypeList({ status: 1, pageSize: 100 })
            if (res.code === ResultEnum.SUCCESS && res.data?.list) {
                // 转换为 valueEnum 格式
                const options: Record<string, { text: string }> = {}
                res.data.list.forEach((item) => {
                    options[item.id] = { text: item.name }
                })
                setServiceTypeOptions(options)
            }
        } catch (e) {
            console.error('获取服务类型列表失败:', e)
        }
    }

    useEffect(() => {
        loadServiceTypeList()
    }, [])

    // 筛选滞留件
    const filterOverdueOrders = () => {
        actionRef.current?.setPageInfo?.({ current: 1 })
        // 设置筛选条件为滞留状态
        formRef.current?.setFieldsValue({ orderStatus: '6' })
        actionRef.current?.reload()
    }

    // 查看订单详情
    const handleViewDetail = (record: OrderManagementTypes.OrderListDto) => {
        navigate(`/order/detail/${record.id}`)
    }

    // 打开备注弹窗
    const openRemarkModal = (record: OrderManagementTypes.OrderListDto) => {
        setSelectedRemark({ orderSn: record.orderSn, remark: record.orderRemark || '暂无备注' })
        setRemarkModalVisible(true)
    }

    // 导出订单
    const handleExport = () => {
        message.info('导出功能开发中')
    }

    // 表格列定义
    const columns: ProColumns<OrderManagementTypes.OrderListDto>[] = [
        {
            title: '订单号',
            dataIndex: 'orderSn',
            key: 'orderSn',
            width: 180,
            render: (text) => (
                <span style={{ fontFamily: 'Courier New, monospace', fontWeight: 500 }}>
                    {text}
                </span>
            ),
        },
        {
            title: '订单类型',
            dataIndex: 'orderTypeId',
            key: 'orderTypeId',
            width: 100,
            hideInTable: true,
            valueType: 'select',
            valueEnum: serviceTypeOptions,
        },
        {
            title: '订单类型',
            dataIndex: 'orderTypeName',
            key: 'orderTypeName',
            width: 100,
            hideInSearch: true,
        },
        {
            title: '柜机名称',
            dataIndex: 'cabinetName',
            key: 'cabinetName',
            width: 140,
        },
        {
            title: '格口编号',
            dataIndex: 'gridNo',
            key: 'gridNo',
            width: 100,
            hideInSearch: true,
            render: (text) => (
                <span style={{ fontFamily: 'Courier New, monospace', fontWeight: 500 }}>
                    {text}
                </span>
            ),
        },
        {
            title: '存件时间',
            dataIndex: 'storeTime',
            key: 'storeTime',
            width: 160,
            hideInSearch: true,
            render: (text) => (
                <span style={{ fontSize: 13, color: '#666' }}>{formatTime(text as number)}</span>
            ),
        },
        {
            title: '取件时间',
            dataIndex: 'pickupTime',
            key: 'pickupTime',
            width: 160,
            hideInSearch: true,
            render: (text) => (
                <span style={{ fontSize: 13, color: '#666' }}>
                    {text ? formatTime(text as number) : '待取件'}
                </span>
            ),
        },
        {
            title: '订单金额',
            dataIndex: 'orderAmount',
            key: 'orderAmount',
            width: 120,
            hideInSearch: true,
            render: (text) => (
                <span style={{ fontFamily: 'Courier New, monospace', fontWeight: 600, color: '#1890ff' }}>
                    ¥{Number(text).toFixed(2)}
                </span>
            ),
        },
        {
            title: '订单状态',
            dataIndex: 'orderStatus',
            key: 'orderStatus',
            width: 100,
            valueType: 'select',
            valueEnum: ORDER_STATUS_VALUE_ENUM,
            render: (_, record) => {
                const status = ORDER_STATUS_MAP[record.orderStatus]
                return (
                    <Badge
                        status={status?.status as any || 'default'}
                        text={status?.text || '未知'}
                    />
                )
            },
        },
        {
            title: '订单备注',
            dataIndex: 'orderRemark',
            key: 'orderRemark',
            width: 100,
            hideInSearch: true,
            render: (_, record) => {
                if (!record.orderRemark) {
                    return <span style={{ color: '#999' }}>-</span>
                }
                return (
                    <Button
                        type="link"
                        size="small"
                        icon={<FileTextOutlined />}
                        onClick={() => openRemarkModal(record)}
                    >
                        查看
                    </Button>
                )
            },
        },
        {
            title: '客诉',
            dataIndex: 'complaintId',
            key: 'complaintId',
            width: 80,
            hideInSearch: true,
            render: (text) => {
                if (text) {
                    return (
                        <Tag color="error" icon={<CommentOutlined />}>
                            有
                        </Tag>
                    )
                }
                return <span style={{ color: '#999' }}>-</span>
            },
        },
        {
            title: '操作',
            key: 'option',
            valueType: 'option',
            fixed: 'right',
            width: 80,
            render: (_, record) => [
                <Tooltip title="查看详情" key={`${record.id}-detail`}>
                    <Button
                        type="link"
                        title="查看详情"
                        icon={<EyeOutlined />}
                        onClick={() => handleViewDetail(record)}
                    />
                </Tooltip>,
            ],
        },
    ]

    return (
        <>
            {/* 滞留件提醒 */}
            <AlertBanner
                visible={overdueCount > 0}
                icon={<ClockCircleOutlined />}
                message="当前有 {count} 件滞留件超期未取，请及时处理"
                count={overdueCount}
                buttonText="筛选滞留件"
                buttonIcon={<ExclamationCircleOutlined />}
                onClick={filterOverdueOrders}
            />

            <ExcelTable
                key="order-list"
                formRef={formRef}
                columns={columns}
                requestFn={async (params) => {
                    const { page, pageSize, orderSn, orderTypeId, orderStatus, cabinetDeviceId, communityId, ...rest } = params
                    return await getOrderList({
                        page,
                        pageSize,
                        orderSn,
                        orderTypeId,
                        orderStatus,
                        cabinetDeviceId,
                        communityId,
                        ...rest
                    })
                }}
                actionRef={actionRef}
                rowSelection={false}
                options={{
                    fullScreen: false,
                    reload: true,
                    setting: false,
                    density: false
                }}
                toolBarRenderFn={() => []}
                scroll={{ x: 1300 }}
            />

            {/* 备注详情弹窗 */}
            <Modal
                title="订单备注"
                open={remarkModalVisible}
                onCancel={() => setRemarkModalVisible(false)}
                footer={[
                    <Button key="close" onClick={() => setRemarkModalVisible(false)}>
                        关闭
                    </Button>,
                ]}
                width={480}
            >
                {selectedRemark && (
                    <div>
                        <div style={{
                            background: '#F8FAFC',
                            borderRadius: 6,
                            padding: 12,
                            marginBottom: 16,
                            fontSize: 13,
                            color: '#64748B'
                        }}>
                            <span>订单号：</span>
                            <span style={{ color: '#1E293B', fontWeight: 500, fontFamily: 'Courier New, monospace' }}>
                                {selectedRemark.orderSn}
                            </span>
                        </div>
                        <div style={{
                            fontSize: 14,
                            color: '#1E293B',
                            lineHeight: 1.6,
                            padding: 12,
                            background: '#FEFCE8',
                            borderRadius: 6,
                            border: '1px solid #FEF08A'
                        }}>
                            {selectedRemark.remark}
                        </div>
                    </div>
                )}
            </Modal>
        </>
    )
}

export default OrderList