import { Button, Card } from 'antd'
import { ReactNode } from 'react'

interface AlertBannerProps {
  /** 是否显示 */
  visible: boolean
  /** 提示图标 */
  icon?: ReactNode
  /** 提示文本，使用 {count} 作为数量占位符 */
  message: string
  /** 数量 */
  count: number
  /** 按钮文本 */
  buttonText: string
  /** 按钮图标 */
  buttonIcon?: ReactNode
  /** 点击回调 */
  onClick: () => void
  /** 自定义样式 */
  style?: React.CSSProperties
  /** 边框颜色 */
  borderColor?: string
  /** 背景颜色 */
  backgroundColor?: string
  /** 文字颜色 */
  textColor?: string
  /** 按钮边框颜色 */
  buttonBorderColor?: string
  /** 按钮文字颜色 */
  buttonTextColor?: string
}

/**
 * 警告提示横幅组件
 * 用于页面顶部显示需要处理的异常数据提醒
 */
const AlertBanner: React.FC<AlertBannerProps> = ({
  visible,
  icon,
  message,
  count,
  buttonText,
  buttonIcon,
  onClick,
  style,
  borderColor = '#FDBA74',
  backgroundColor = '#FFF7ED',
  textColor = '#9A3412',
  buttonBorderColor = '#FDBA74',
  buttonTextColor = '#9A3412'
}) => {
  if (!visible) {
    return null
  }

  return (
    <Card
      style={{
        marginBottom: 16,
        borderColor,
        background: backgroundColor,
        ...style
      }}
      styles={{ body: { padding: '12px 16px' } }}
    >
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between'
        }}
      >
        <div style={{ color: textColor, fontSize: 14 }}>
          {icon && <span style={{ marginRight: 8 }}>{icon}</span>}
          <span
            dangerouslySetInnerHTML={{
              __html: message.replace('{count}', `<b>${count}</b>`)
            }}
          />
        </div>
        <Button
          size="small"
          style={{
            borderColor: buttonBorderColor,
            color: buttonTextColor
          }}
          onClick={onClick}
          icon={buttonIcon}
        >
          {buttonText}
        </Button>
      </div>
    </Card>
  )
}

export default AlertBanner
